// HTML partials are imported as raw strings (webpack asset/source).
declare module '*.html' {
  const content: string;
  export default content;
}

// Image assets are imported as resource URLs (webpack asset/resource).
declare module '*.jpg' {
  const src: string;
  export default src;
}

declare module '*.jpeg' {
  const src: string;
  export default src;
}

declare module '*.png' {
  const src: string;
  export default src;
}

declare module '*.gif' {
  const src: string;
  export default src;
}

declare module '*.svg' {
  const src: string;
  export default src;
}

declare module '*.webp' {
  const src: string;
  export default src;
}
